import React, { useState, useEffect, useMemo, memo, useCallback } from "react";
import { useI18n } from "../contexts/I18nContext";
import { useStatus } from "../contexts/StatusContext";
import { Client } from "../types/api";
import "../animations.css";
import {
  CpuIcon,
  CheckIcon,
  AlertIcon,
  ProcessingIcon,
  MemoryIcon,
  SpeedIcon,
  AnimatedHeartIcon,
  WarningIcon,
  ErrorIcon,
} from "./Icons";

interface WorkerMetricsData {
  timestamp: string;
  cpu_usage: number;
  memory_usage: number;
  active_tasks: number;
  completed_tasks: number;
  failed_tasks: number;
  response_time: number;
}

// Новий інтерфейс для системних ресурсів
interface SystemResourceData {
  cpu_usage: number;
  memory_usage: number;
  disk_usage: number;
  network_in: number;
  network_out: number;
  uptime: number;
}

interface WorkerMetricsProps {
  clients: Client[];
}

// API функції для отримання реальних даних
const API_BASE_URL = 'http://localhost:8000';

const fetchHubMetrics = async (): Promise<any> => {
  try {
    const response = await fetch(`${API_BASE_URL}/dashboard/api/hub-metrics`);
    if (!response.ok) throw new Error('Failed to fetch hub metrics');
    return await response.json();
  } catch (error) {
    console.error('Error fetching hub metrics:', error);
    return null;
  }
};

const fetchClientMetrics = async (clientId: string): Promise<WorkerMetricsData[]> => {
  try {
    const response = await fetch(`${API_BASE_URL}/dashboard/api/clients/${clientId}/metrics`);
    if (!response.ok) throw new Error(`Failed to fetch metrics for client ${clientId}`);
    const data = await response.json();

    // Перетворюємо дані з API у формат WorkerMetricsData
    if (data.metrics && Array.isArray(data.metrics)) {
      return data.metrics.map((metric: any) => ({
        timestamp: metric.timestamp || new Date().toISOString(),
        cpu_usage: metric.cpu_usage || 0,
        memory_usage: metric.memory_usage || 0,
        active_tasks: metric.active_tasks || 0,
        completed_tasks: metric.completed_tasks || 0,
        failed_tasks: metric.failed_tasks || 0,
        response_time: metric.response_time || 0,
      }));
    }

    return [];
  } catch (error) {
    console.error(`Error fetching metrics for client ${clientId}:`, error);
    return [];
  }
};

const fetchRealTimeMetrics = async (): Promise<any> => {
  try {
    const response = await fetch(`${API_BASE_URL}/dashboard/api/real-time-metrics`);
    if (!response.ok) throw new Error('Failed to fetch real-time metrics');
    return await response.json();
  } catch (error) {
    console.error('Error fetching real-time metrics:', error);
    return null;
  }
};

// Компонент системного моніторингу ресурсів
const SystemResourceMonitor: React.FC<{ 
  selectedClient?: Client | null;
  resourceData?: SystemResourceData;
}> = ({ selectedClient, resourceData }) => {
  const { t } = useI18n();
  const { state } = useStatus();
  const [realTimeData, setRealTimeData] = useState<any>(null);

  // Отримуємо реальні дані з API
  useEffect(() => {
    const fetchData = async () => {
      const hubMetrics = await fetchHubMetrics();
      const rtMetrics = await fetchRealTimeMetrics();

      if (hubMetrics || rtMetrics) {
        setRealTimeData({ hub: hubMetrics, realTime: rtMetrics });
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 5000); // Оновлюємо кожні 5 секунд

    return () => clearInterval(interval);
  }, [selectedClient]);

  const getUsageColor = (value: number) => {
    if (value > 80) return "bg-red-500";
    if (value > 60) return "bg-yellow-500";
    return "bg-green-500";
  };

  const getUsageTextColor = (value: number) => {
    if (value > 80) return "text-red-600";
    if (value > 60) return "text-yellow-600";
    return "text-green-600";
  };

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  };

  const formatUptime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}г ${minutes}хв`;
  };

  // Використовуємо реальні дані з API
  const systemData = resourceData || {
    cpu_usage: realTimeData?.hub?.system?.cpu_usage || realTimeData?.realTime?.performance_data?.cpu_usage || 0,
    memory_usage: realTimeData?.hub?.system?.memory_usage || realTimeData?.realTime?.performance_data?.memory_usage || 0,
    disk_usage: realTimeData?.hub?.system?.disk_usage || 0,
    network_in: realTimeData?.realTime?.performance_data?.network_io || 0,
    network_out: realTimeData?.realTime?.performance_data?.network_io || 0,
    uptime: realTimeData?.hub?.uptime || state.health?.uptime || 0,
  };

  const resources = [
    {
      name: "CPU",
      value: systemData.cpu_usage,
      icon: <CpuIcon size="md" className="text-blue-600" />,
      color: "blue",
    },
    {
      name: t("dashboard.memory"),
      value: systemData.memory_usage,
      icon: <MemoryIcon size="md" className="text-green-600" />,
      color: "green",
    },
    {
      name: t("dashboard.disk"),
      value: systemData.disk_usage,
      icon: "💿",
      color: "purple",
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6 flex items-center">
        📊 {t("dashboard.resourceMonitor")}
        {selectedClient && (
          <span className="ml-2 text-sm text-secondary-600 font-normal">
            - {selectedClient.client_name || selectedClient.client_id}
          </span>
        )}
      </h3>

      <div className="space-y-6">
        {resources.map((resource, index) => (
          <div
            key={resource.name}
            className="space-y-3 p-4 bg-secondary-50 rounded-lg hover:bg-secondary-100 transition-colors duration-200"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                {typeof resource.icon === 'string' ? (
                  <span className="text-2xl">{resource.icon}</span>
                ) : (
                  resource.icon
                )}
                <span className="text-base font-medium text-secondary-800">
                  {resource.name}
                </span>
              </div>
              <span className={`text-lg font-bold ${getUsageTextColor(resource.value)}`}>
                {Math.round(resource.value)}%
              </span>
            </div>
            <div className="w-full bg-secondary-200 rounded-full h-3">
              <div
                className={`h-3 rounded-full transition-all duration-500 ${getUsageColor(resource.value)}`}
                style={{ width: `${Math.min(resource.value, 100)}%` }}
              />
            </div>
          </div>
        ))}

        {/* Мережева активність */}
        <div className="grid grid-cols-2 gap-4 mt-6">
          <div className="text-center p-4 bg-blue-50 rounded-lg">
            <p className="text-lg font-bold text-blue-600">
              {formatBytes(systemData.network_in * 1024 * 1024)}
            </p>
            <p className="text-sm text-blue-700">{t("dashboard.incomingTraffic")}</p>
          </div>
          <div className="text-center p-4 bg-green-50 rounded-lg">
            <p className="text-lg font-bold text-green-600">
              {formatBytes(systemData.network_out * 1024 * 1024)}
            </p>
            <p className="text-sm text-green-700">{t("dashboard.outgoingTraffic")}</p>
          </div>
        </div>

        {/* Час роботи */}
        {systemData.uptime > 0 && (
          <div className="pt-4 border-t border-secondary-200">
            <div className="flex justify-between items-center">
              <span className="text-sm text-secondary-600">{t("dashboard.systemUptime")}</span>
              <span className="text-lg font-bold text-purple-600">
                {formatUptime(systemData.uptime)}
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const MetricChart: React.FC<{
  title: string;
  data: WorkerMetricsData[];
  dataKey: keyof WorkerMetricsData;
  color: string;
  unit?: string;
}> = memo(
  ({ title, data, dataKey, color, unit = "" }) => {
    const { maxValue, minValue, range, points, yAxisLabels } = useMemo(() => {
      // Handle empty or invalid data
      if (!data || data.length === 0) {
        return { maxValue: 0, minValue: 0, range: 1, points: [], yAxisLabels: [] };
      }

      const values = data.map((d) => {
        const val = Number(d[dataKey]);
        return isNaN(val) ? 0 : val;
      }).filter(val => !isNaN(val));

      if (values.length === 0) {
        return { maxValue: 0, minValue: 0, range: 1, points: [], yAxisLabels: [] };
      }

      const max = Math.max(...values);
      const min = Math.min(...values);

      // Додаємо відступи для кращого відображення
      const padding = (max - min) * 0.1 || 1;
      const adjustedMax = max + padding;
      const adjustedMin = Math.max(0, min - padding);
      const r = adjustedMax - adjustedMin || 1;

      // Розміри графіка
      const chartWidth = 340;
      const chartHeight = 120;
      const leftMargin = 60;
      const topMargin = 20;

      const chartPoints = data.map((point, index) => {
        const x = leftMargin + (index * chartWidth) / Math.max(data.length - 1, 1);
        const value = Number(point[dataKey]);
        const safeValue = isNaN(value) ? 0 : value;
        const y = topMargin + chartHeight - ((safeValue - adjustedMin) / r) * chartHeight;
        return { 
          x, 
          y: isNaN(y) ? topMargin + chartHeight : Math.max(topMargin, Math.min(topMargin + chartHeight, y)), 
          value: safeValue, 
          timestamp: point.timestamp 
        };
      });

      // Генеруємо лейбли для Y-осі
      const labelCount = 5;
      const yLabels = Array.from({ length: labelCount }, (_, i) => {
        const value = adjustedMax - (i * r) / (labelCount - 1);
        const y = topMargin + (i * chartHeight) / (labelCount - 1);
        return { value, y };
      });

      return { 
        maxValue: adjustedMax, 
        minValue: adjustedMin, 
        range: r, 
        points: chartPoints,
        yAxisLabels: yLabels
      };
    }, [data, dataKey]);

    return (
      <div className="bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg">
        <h3 className="text-lg font-semibold text-secondary-900 mb-4">
          {title}
        </h3>
        <div className="relative h-56">
          {points.length === 0 ? (
            <div className="flex items-center justify-center h-full">
              <p className="text-secondary-500 text-sm">Немає даних для відображення</p>
            </div>
          ) : (
            <svg className="w-full h-full" viewBox="0 0 420 180" preserveAspectRatio="xMidYMid meet">
              {/* Grid lines */}
              {yAxisLabels.map((label, i) => (
                <line
                  key={i}
                  x1="60"
                  y1={label.y}
                  x2="400"
                  y2={label.y}
                  stroke="#f3f4f6"
                  strokeWidth="1"
                />
              ))}

              {/* Y-axis */}
              <line
                x1="60"
                y1="20"
                x2="60"
                y2="140"
                stroke="#e5e7eb"
                strokeWidth="1"
              />

              {/* X-axis */}
              <line
                x1="60"
                y1="140"
                x2="400"
                y2="140"
                stroke="#e5e7eb"
                strokeWidth="1"
              />

              {/* Y-axis labels */}
              {yAxisLabels.map((label, i) => (
                <text
                  key={i}
                  x="55"
                  y={label.y + 4}
                  textAnchor="end"
                  className="text-xs fill-secondary-500"
                  fontSize="10"
                >
                  {label.value.toFixed(1)}{unit}
                </text>
              ))}

              {/* Chart area background */}
              <rect
                x="60"
                y="20"
                width="340"
                height="120"
                fill="transparent"
                stroke="none"
              />

              {/* Chart line */}
              {points.length > 1 && (
                <polyline
                  fill="none"
                  stroke={color}
                  strokeWidth="2.5"
                  points={points.map((p) => `${p.x},${p.y}`).join(" ")}
                  style={{
                    strokeDasharray: "1000",
                    strokeDashoffset: "1000",
                    animation: "drawLine 2s ease-out forwards",
                  }}
                />
              )}

              {/* Area fill under line */}
              {points.length > 1 && (
                <polygon
                  fill={color}
                  fillOpacity="0.1"
                  points={`
                    ${points.map((p) => `${p.x},${p.y}`).join(" ")}
                    ${points[points.length - 1].x},140
                    ${points[0].x},140
                  `}
                />
              )}

              {/* Data points */}
              {points.map((point, index) => (
                <g key={index}>
                  <circle
                    cx={point.x}
                    cy={point.y}
                    r="4"
                    fill="white"
                    stroke={color}
                    strokeWidth="2"
                    className="hover:r-6 transition-all cursor-pointer"
                  />
                  <circle
                    cx={point.x}
                    cy={point.y}
                    r="2"
                    fill={color}
                  />
                  <title>{`${title}: ${point.value.toFixed(2)}${unit}\nЧас: ${new Date(point.timestamp).toLocaleTimeString()}`}</title>
                </g>
              ))}

              {/* Current value indicator */}
              {points.length > 0 && (
                <g>
                  <text
                    x={points[points.length - 1].x}
                    y={points[points.length - 1].y - 10}
                    textAnchor="middle"
                    className="text-xs font-semibold"
                    fill={color}
                    fontSize="11"
                  >
                    {points[points.length - 1].value.toFixed(1)}{unit}
                  </text>
                </g>
              )}
            </svg>
          )}
        </div>
      </div>
    );
  },
  (prevProps, nextProps) => {
    // Custom comparison for MetricChart
    return (
      prevProps.title === nextProps.title &&
      prevProps.dataKey === nextProps.dataKey &&
      prevProps.color === nextProps.color &&
      prevProps.unit === nextProps.unit &&
      prevProps.data.length === nextProps.data.length &&
      prevProps.data.every(
        (item, index) =>
          item[prevProps.dataKey] ===
          nextProps.data[index]?.[nextProps.dataKey],
      )
    );
  },
);

